using System;

namespace StdbModule;

public static partial class TurkishQuotes
{
    public static class AzizNesin
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Göz ve ışık, ancak görmesini isteyen ve bilenlerin işine yarar.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Biz halisinden Atatürkçüyüz ve Atatürk hazretlerinin izindeyiz. Öyle yatıra matıra, türbeye, kıtıra inanmayız.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Biz böyleyiz, bizden ne köy olur ne kasaba... Böyle gelmiş, böyle gideriz. Lanetlendik mi, beddua mı aldık nedir? Çilemizdir çekeceğiz...", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bu devir namussuz devri. Kimse doğruluk üzerine iş görmüyor. Doğru adamı hiçbir işin başına geçirmiyorlar.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Hepimize attığı kazıkların bir ucu gök kubbesine, bir ucu yerin yedi kat dibine varmış. Şimdi biz yediğimiz kazıklar çıkar mı diyerek bile bile bir yalana daha göz yumuyoruz. Kazıklandıkça, insanın yalana inanası geliyor.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Doktorlar anlamadı ama, ben hastayım. Hastalığımı biliyorum: Umutsuzluk , kırgınlık... Ruh çöküntüsü içinde gittikçe kendimden ayrılıp başka bir insan oluyorum.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Şimdi çok iyi anladım ki; bizde zübük bir tane değil, biz hepimiz birer zübüğüz. Hepimizin içinde zübüklük olmasa, bizler de birer zübük olmasak, aramızdan böyle zübükler büyüyemezdi.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Öyle ya. Bu adam bir kere siyasete gözünü dikmiş. Böylesinden korkulur. Bunun yapmayacağı kötülük yoktur.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Yavru larım, yurtsever olunuz. Yurdunuzu çok, çok seviniz. Yurdunuzu yakından tanıyanız. Büyüyünce Anadolu'yu köy köy dolaşınız. Yoksul yerlerde görev alınız. Bu Cumhuriyet size emanettir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Delilik, en sağlam dokunulmazlıktır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "İster kadın ister erkek olalım, kendi kendimizden memnunsak, şanslıyız demektir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Yalnız kendi öz çocuklarımı değil, yalnız Türk çocuklarını değil, Amerikan, Rus, Alman, Ermeni, Çin, Çingene bütün çocukları seviyorum.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "İnsan bir küçücük yalan söyledi mi, o yalanı gizlemek için biraz daha büyük yalan söylemek zorunda kalır. Sonra o yalan ortaya çıkmasın diye daha büyük yalan söyler.Her yalan, daha çok, daha büyük yalan doğurur.Onun için yalan söyleme!", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Çocuklara daha iyi bir dünya bırakmak yerine, dünyaya daha iyi çocuklar bıraksanız, sorun kendiliğinden çözülecek aslında.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bir davranış fedakarlık olsun, bunu herkes bilsin, duysun diye yapıldı mı, o davranış fedakarlık olmaktan çıkıyor.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "İçinde bulunduğumuz mutluluğu bilemeyiz. Ancak ondan uzaklaşınca, mutluluk içinde yaşadığımızı anlarız.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Aman oğlum, artık okuma, aklın karışır da iş adamı olamazsın.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Çocuklar, ben anladım bu vicdan azabı denilen şeyi. Hiç kimse kendisininkini hatırlamıyor. Herkes başkalarının çekmesi gereken vicdan azabını biliyor.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Ben terbiyeyi, terbiyesizlerden öğrendim.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Politikacıdır bu, herkesi öper de, sever de, kucaklar da...", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Yok oğlum, yok; medeniyetin okulu, kursu mursu olmaz. İnsanın kendinde olmayınca ne yapsan boş.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bu dünyada milyarlarca insan var, hepsi de başka başka. Hiçbiri birbirine benzemez..", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "\"Diploman var mı, okul diploman?\" dedi. \"Yok, dedim, okula gidemedim.\" \"Hmmm, demek diploman yok. Öyleyse sana yüksek bir iş vereceğiz,\" dedi.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Benim deli olmam olanaksız. Çünkü ben ölmüşüm. Deliler de ölür ama hiç ölüler delirir mi?", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Hatta vali bile olmak için, hatta elçi bile olmak için diploma gerekmez de, mahalle bekçisi olmaya kalksan diploma ister.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Okula gideceksem, yaşamıyorum. Askere alacaklarsa, yaşıyorum. Nüfus kağıdı istersem, yaşamıyorum. Vergi alacaklarsa, yaşıyorum. İş ararsam, yaşamıyorum. Ceza keseceklerse, yaşıyorum.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "İnsanın bir dili öğrenmiş olduğu üç şeyden anlaşılır. Birincisi, o dilde rüya görüyorsa. İkincisi o dilde sevişiyorsa. Üçüncüsü de, o dilde kavga edebiliyorsa.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bir şeyi bedava dediler mi aman alma sakın, oradan kaç. Bedeline almaktan çok daha pahalıya gelir!", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Ben de susuyorum sevgimi saklayıp içimde.. Duyuyorsun değil mi suskunluğumu nasıl haykırıyor.. Susarak sevgisini ilan eden çok var sevgilim .. Ama bir başka seven yok benim sustuğum biçimde..", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Kendisi çatlamadan Toprağı çatlatamaz tohum", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bir tohum verdin çiçeğini al. Bir çekirdek verdin ağacını al. Bir dal verdin ormanını al. Dünyamı verdim sana bende kal.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Al yalnızlığını gel! Korkma, sıkılmayız. Senin yalnızlığın, benim yalnızlığımla konuşur. Biz susarız.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Aç bırak itaat etsin, cahil bırak biat etsin!", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Nâzım'ın mezarı bir utanç belgesi olarak Moskova'da kalsın ki, kuşaklar boyunca ne büyük yanlış yaptığımızı anımsayıp utanalım. Tarih salt övünmek için değil utanmak içindir de..", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Nâzım'ın şiirleri, şiirde propagandanın estetik düzeyde nasıl yapıldığının en güzel örnekleridir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Ne zekası? Bu milletin yüzde doksan biri 82 Anayasası'na evet demiştir. Geriye kalıyor yüzde dokuz. Hadi biraz iyimser olalım, ama yüzde altmışı aptal bir milletiz.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Yüzde altmışımız aptalsak, yüzde doksanımız da korkağız.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Sondan bir önceki hiçbir görevini yapmayanların, \"son görevimizi yapıyoruz\" deme ikiyüzlülüğünden tiksiniyorum.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Alevi değilsin ki sana ne oluyor? dedi, ben de insan değilsin ki nasıl anlatayım dedim.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Türkiye'de kimse kazık kendisine girmedikçe, başkalarının yediği kazıkla ilgilenmez.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bana dokunmayan yılan bin yıl yaşasın diyerek, yaşattığınız yılanların bir sonraki hedefi siz olursunuz.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Türk erkeğinin dünyanın en kıskanç erkeklerinden biri olmasının sebebi; sevgililerine değil, kendilerine güvenmediklerindendir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Korkmuyorum diyenler ya başkalarına yalan söylüyorlar, ya kendilerine yalan söyleyip kendilerini kandırıyorlar ya da bilmeyerek insan olmadıklarını söylüyorlar.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Türkiye'de her üç kişiden dördü şairdir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bahse girerim yarın bir yobaz çıkıp, \"tuvalete gitmek günah\" diye fetva verse, tuvalete gitmeyecek ve altına yapacak o kadar öküz var ki bu ülkede!", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Alıştın nutukları dinleyip uyuyorsun. Sen böyle uyudukça sanma ki sabah olur. Körler memleketinde şaşı padişah olur!", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Ben bir ateistim ve eğer bir gün Tanrı'ya inandığımı söylediğimi duyarsanız ciddiye almayın. Bunamışımdır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bırak olmasın mezar taşımız, bir okul bahçesine gömsünler bizi çocuklar koşsun üzerimizde..", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Türkiye'de İslam, Diyanet İşleri Başkanlığı aracılığıyla ve hükümet yoluyla devletin içindedir. Böyle olunca devletle din işleri birbirinden ayrılmıyor. Yani Türkiye, laik değil demektir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bu film çok saçma, ben milletimi bilirim, o kadar Türk bir otobüste İsveç'in ortasında bir hafta kalacak ve dışarı bile çıkmayacaklar, o kadar zamanda o Türkler dışarı çıkar, üç-beş sarışın hatun düdükler, iki de kebapçı dükkânı açar.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Hiçbir Müslüman Atatürk'ü sevmez, niye sevsin ki? Yaptığı hiçbir şey İslam'ın lehine değildir. Eğer bir Müslüman hem Atatürk'ü seviyor, hem de Müslümansa ya ahmaktır, ya sahtekâr!", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "İnsanın insanlardan kaçışıdır, hayvan sevgisi.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Seni, annen kadar sevecek ve baban kadar merak edecek hiç kimse yoktur; o yüzden kimse bana aşk'tan bahsetmesin.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Silahlanmaya ödenen para, dünyadaki açlık sorununun tamamen halledilmesi için gereken paranın yaklaşık 100 katıdır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Yoksulun tek silahı çalışmaktır. Tembellerin ise çalışma günü yarındır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "İsterse Mustafa Kemal Atatürk söylemiş olsun; en değerli sözler bile, zamanı geçince ve koşullar değişince, eskir, yıpranır, değerini yitirir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Din faktörünün bu kadar öne çıktığı bir toplum, nasıl oluyor da beri tarafta çok haram yiyor?", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Nerde din ve ulusalcılık varsa, orada kesinlikle savaş da vardır. Tarih bu kanlı din ve ulusalcılık savaşlarıyla doludur.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Nerde din ve milliyetçilik varsa, orada kesinlikle savaş da vardır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Faşist devlet felsefesinde devlet, babadır. Kapitalist devlet felsefesindeyse devlet, sahip çıkılması gereken, zavallı, garip, bakımsız, kimsesiz bir çocuktur ve ona sahip çıkılmalıdır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Türkiye halkı, ulaştığı oranda bile olsa, elde ettiği demokrasinin, Türkiye işçi sınıfı da kavuştuğu ölçüde bile olsa kazandığı sendikal haklarının bedelini ödememiştir. Hep hazırcıdır ve haklar yukardan verilerek hazıra konmuştur.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Evet, Kenan Evren tarihe kötü yönetimiyle geçecektir; geçecek değil, geçmiştir bile..", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bir insanın, başka birinin yalan söylediğine inanması için, kendisinin öyle bir yalanı söyleyebilir olması gerekir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Laik bir devlette en laik olması gereken kurum eğitimdir.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Türkiye gibi bozuk düzenli toplumlarda insanların sevdikleri işi yapabilmeleri, hele yoksul kökenli olanlar için, çok seyrek görülebilen şanstır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Türkiye'de bolluğun olduğu yalandır. Türkiye'de herkes yeterince et yiyebilseydi, hiç kimseye et yetmezdi; herkes yeterince süt içseydi kimseye süt yetmezdi.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Korkunun ana kaynağı sermayedir. Kapitalizm, her zaman ve her yerde korku üretecektir. Çünkü, sermaye korkaktır ve korkan hep korkutmak zorundadır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Korkudan korkan insanların kendilerine güveni kalmaz. Köleleşirler, uşaklaşırlar ve üstelik kendilerini özgür ve efendi de sanırlar.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Eleştirinin amacı eleştiri değil, doğruyu bulmaktır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Mustafa Kemal Türkiyesi; yabancılardan on para borç almadan, sömürgenlerden yardım dilenmeden, demiryollarıyla, endüstrisiyle, her şeyiyle kurulmuştur.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Her zorba herkesten her istediğini alabilir, ama yaşayan günlerini alamaz.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Kapitalist ülkelerde tüccarların, sosyalist ülkelerde de yazarların durumları çok iyidir. Yani işini bilen bir insan, sosyalist ülkedeyse yazar, kapitalist ülkedeyse tüccar olmalıdır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Bazen insan öyle özlenir ki; özlenen bilse yokluğundan utanır..", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Yağma, kıyım, yıkım... Bu üç sözcük yeterlice açıklayabiliyor mu 6-7 Eylül olaylarını? Sanmıyorum.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Yaşamıyorum, yazıyorum; çünkü yaşamak benim için yazmaktır.", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "Türkiye hasta! Ahlaken hasta, düşünce olarak hasta, eylem olarak hasta! Gerçekten hasta!", Author = "Aziz Nesin" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Aziz_Nesin", Text = "İnanmak inananların nasıl hakkıysa, inanmamak da inanmayanların hakkıdır.", Author = "Aziz Nesin" },
        };
    }
}